const filter = typeof filterName === 'string' ? filterName : 'ores';
const found = drone.scanBlocks({ filter: filter, radius: 24 });
if (!found.count) return { ok: false, error: 'no matching blocks within 24m', hint: 'scan wider or move to another area' };
const mined = [];
for (var i = 0; i < found.blocks.length && i < 8; i++) {
  const block = found.blocks[i];
  const moved = drone.goto({ standoffOf: { x: block.x, y: block.y, z: block.z } });
  if (!moved.arrived) continue;
  const broke = drone.breakBlock({ x: block.x, y: block.y, z: block.z });
  if (broke.ok !== false && broke.broken) mined.push(block);
}
return { mined: mined.length, blocks: mined, remaining: Math.max(0, (found.count || 0) - mined.length) };
